use serde::{Deserialize, Serialize};
use std::collections::HashSet;

use super::error::{DomainError, DomainResult};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ChecklistItem {
    pub id: String,
    pub text: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Checklist {
    pub id: String,
    pub name: String,
    pub items: Vec<ChecklistItem>,
}

impl Checklist {
    /// Ids are opaque and generated by the frontend; here they are only
    /// checked for presence and uniqueness. Name uniqueness across lists is
    /// enforced by the service, which can see the other lists.
    pub fn new(
        id: impl Into<String>,
        name: impl Into<String>,
        items: Vec<ChecklistItem>,
    ) -> DomainResult<Self> {
        let id = id.into().trim().to_string();
        let name = name.into().trim().to_string();
        let mut seen = HashSet::new();
        if id.is_empty()
            || items
                .iter()
                .any(|i| i.id.trim().is_empty() || !seen.insert(i.id.as_str()))
        {
            return Err(DomainError::ChecklistInvalidId);
        }
        if name.is_empty() {
            return Err(DomainError::ChecklistEmptyName);
        }
        if items.is_empty() {
            return Err(DomainError::ChecklistNoItems);
        }
        if let Some(index) = items.iter().position(|i| i.text.trim().is_empty()) {
            return Err(DomainError::ChecklistEmptyItem { index });
        }
        let items = items
            .into_iter()
            .map(|i| ChecklistItem {
                id: i.id,
                text: i.text.trim().to_string(),
            })
            .collect();
        Ok(Self { id, name, items })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn item(id: &str, text: &str) -> ChecklistItem {
        ChecklistItem {
            id: id.to_string(),
            text: text.to_string(),
        }
    }

    #[test]
    fn trims_name_and_item_texts_on_creation() {
        let list =
            Checklist::new("l1", "  Pre-stream  ", vec![item("i1", "  Check mic ")]).unwrap();
        assert_eq!(list.name, "Pre-stream");
        assert_eq!(list.items[0].text, "Check mic");
    }

    #[test]
    fn rejects_empty_list_id() {
        assert!(matches!(
            Checklist::new("  ", "Pre-stream", vec![item("i1", "a")]),
            Err(DomainError::ChecklistInvalidId)
        ));
    }

    #[test]
    fn rejects_empty_item_id() {
        assert!(matches!(
            Checklist::new("l1", "Pre-stream", vec![item("i1", "a"), item(" ", "b")]),
            Err(DomainError::ChecklistInvalidId)
        ));
    }

    #[test]
    fn rejects_duplicate_item_ids() {
        assert!(matches!(
            Checklist::new("l1", "Pre-stream", vec![item("i1", "a"), item("i1", "b")]),
            Err(DomainError::ChecklistInvalidId)
        ));
    }

    #[test]
    fn rejects_empty_name() {
        assert!(matches!(
            Checklist::new("l1", "   ", vec![item("i1", "a")]),
            Err(DomainError::ChecklistEmptyName)
        ));
    }

    #[test]
    fn rejects_zero_items() {
        assert!(matches!(
            Checklist::new("l1", "Pre-stream", vec![]),
            Err(DomainError::ChecklistNoItems)
        ));
    }

    #[test]
    fn rejects_item_with_blank_text() {
        assert!(matches!(
            Checklist::new("l1", "Pre-stream", vec![item("i1", "a"), item("i2", "  ")]),
            Err(DomainError::ChecklistEmptyItem { index: 1 })
        ));
    }

    #[test]
    fn keeps_item_order_and_duplicate_texts() {
        let list = Checklist::new(
            "l1",
            "Pre-stream",
            vec![item("i1", "a"), item("i2", "a"), item("i3", "b")],
        )
        .unwrap();
        let texts: Vec<_> = list.items.iter().map(|i| i.text.as_str()).collect();
        let ids: Vec<_> = list.items.iter().map(|i| i.id.as_str()).collect();
        assert_eq!(texts, ["a", "a", "b"]);
        assert_eq!(ids, ["i1", "i2", "i3"]);
    }
}
